USE travelstart;

-- Drop tables if they exist
DROP TABLE IF EXISTS wards;
DROP TABLE IF EXISTS lgas;
DROP TABLE IF EXISTS states;

-- Create States table with alphanumeric IDs
CREATE TABLE states (
    state_id VARCHAR(15) PRIMARY KEY,
    state_name VARCHAR(255) UNIQUE NOT NULL
);

-- Create LGAs table with alphanumeric IDs
CREATE TABLE lgas (
    lga_id VARCHAR(15) PRIMARY KEY,
    lga_name VARCHAR(255) NOT NULL,
    state_id VARCHAR(15) NOT NULL,
    FOREIGN KEY (state_id) REFERENCES states(state_id) ON DELETE CASCADE
);

-- Create Wards table with alphanumeric IDs
CREATE TABLE wards (
    ward_id VARCHAR(15) PRIMARY KEY,
    ward_name VARCHAR(255) NOT NULL,
    lga_id VARCHAR(15) NOT NULL,
    FOREIGN KEY (lga_id) REFERENCES lgas(lga_id) ON DELETE CASCADE
);

